    auto writeInterMotionDelta(Bitstream::Writer &bw, uint32_t index) -> void
    {
        REQUIRE(index < (1 << DeltaLongCodeLength), std::runtime_error, "Index must be < " << (1 << DeltaLongCodeLength));
        if (index < (1 << DeltaShortCodeLength))
        {
            bw.push(index, DeltaShortCodeLength + 1);
        }
        else
        {
            bw.push(index | (1 << DeltaLongCodeLength), DeltaLongCodeLength + 1);
        }
    }

    auto readInterMotionDelta(Bitstream::Reader &br) -> DeltaVector
    {
        if (br.pop(1) == 0)
        {
            return DeltaVectors[br.pop(DeltaShortCodeLength)];
        }
        else
        {
            return DeltaVectors[br.pop(DeltaLongCodeLength)];
        }
    }

